// =================== DERMATOLOGIA ===================
export const dermatologyEmergencyProtocols: EmergencyProtocol[] = [
  {
    id: "sjs-ten",
    title: "Stevens-Johnson / Necrólise Epidérmica Tóxica (NET)",
    categoryId: "dermatology-emergency",
    sections: [
      { id: "intro", title: "Introdução", content: "A síndrome de Stevens-Johnson (SJS) e a necrólise epidérmica tóxica (NET/Lyell) são reações mucocutâneas graves mediadas por células T, geralmente induzidas por medicamentos. A NET tem mortalidade de 30–50%. O diagnóstico precoce, a suspensão do agente causador e internação em unidade especializada são fundamentais.\n\n⚕️ Uso exclusivo por profissional de saúde habilitado. Última revisão: Mai/2026." },
      { id: "def", title: "Definição", content: "Espectro da mesma doença diferenciado pela área de superfície corporal (ASC) acometida:\n• Eritema Multiforme (EM) Major: < 10% ASC, lesões em alvo típicas (não induzido por droga)\n• Stevens-Johnson (SJS): < 10% ASC, máculas eritematosas com bolhas\n• Sobreposição SJS-NET: 10–30% ASC\n• Necrólise Epidérmica Tóxica (NET): > 30% ASC, descolamento extenso\n\nEscore SCORTEN (mortalidade):\n• Idade > 40, frequência cardíaca > 120, malignidade, ASC > 10%, ureia > 28, glicemia > 252, bicarbonato < 20\n→ 1 ponto cada: SCORTEN ≥ 5 = mortalidade > 90%" },
      { id: "screening", title: "Rastreamento e Identificação", content: "Medicamentos mais frequentemente causadores:\n• Alopurinol (principal no Brasil e Ásia)\n• Antibióticos: sulfonamidas (cotrimoxazol), aminopenicilinas, quinolonas\n• Anticonvulsivantes: carbamazepina, fenitoína, lamotrigina, fenobarbital\n• AINEs: piroxicam, tenoxicam\n• Nevirapina (HIV)\n• Inibidores de checkpoint (imunoterapia oncológica)\n\nLatência: 2–8 semanas após início do medicamento\n\nSinais de alerta: febre + lesões de mucosa + eritema com bolhas" },
      { id: "etiology", title: "Etiologia", content: "Mecanismo:\n• Células T citotóxicas (CD8+) reagem ao medicamento → apoptose maciça de ceratinócitos → descolamento epidermal\n• Granzima B, perforina, FasL — morte celular\n• Fator genético: HLA-B*15:02 (carbamazepina em asiáticos), HLA-B*58:01 (alopurinol)" },
      { id: "clinical", title: "Apresentação Clínica", content: "Pródromo (1–3 dias antes das lesões):\n• Febre alta (38–40°C)\n• Mal-estar intenso, mialgia\n• Odinofagia, conjuntivite\n• Sintomas de IVAS\n\nFase de exantema:\n• Eritema difuso que progride para máculas purpúricas\n• Bolhas flácidas (sinal de Nikolsky positivo: tração lateral da pele → descolamento)\n• Erosões de mucosas: oral (dolorosa), ocular, genital\n\nFase de descolamento (NET):\n• Grandes áreas de necrose e descolamento epidermal\n• Aspecto de 'pele escaldada' / 'grande queimado'\n• Erosões hemorrágicas extensas" },
      { id: "diagnosis", title: "Diagnóstico", content: "Clínico + sinal de Nikolsky + histórico de medicamento\n\nBiópsia de pele:\n• Padrão: apoptose de ceratinócitos em toda espessura epidérmica (pan-epidérmica)\n• Necrose epidérmica com separação na junção dermoepidérmica\n\nLaboratório:\n• Hemograma: leucocitose ou leucopenia\n• PCR\n• Eletrólitos, albumina\n• Função renal e hepática\n• Hemoculturas (infecção secundária)\n• Calcular SCORTEN (prognóstico)" },
      { id: "differential", title: "Diagnóstico Diferencial", content: "• Pênfigo vulgar (sem prodromos sistêmicos, lesão oral crônica)\n• Síndrome da pele escaldada estafilocócica (SSSS): crianças, sem lesão mucosa, clivagem subcorneal\n• Eritrodermia (> 90% da superfície, sem bolhas significativas)\n• Doença do enxerto contra hospedeiro (GVHD)" },
      { id: "conduct", title: "Conduta", content: "1. SUSPENDER MEDICAMENTO CAUSADOR IMEDIATAMENTE\n   • Cada dia adicional com a droga aumenta mortalidade\n\n2. INTERNAÇÃO EM UTI DERMATOLÓGICA ou UNIDADE DE QUEIMADOS:\n   • Temperatura ambiente elevada (28–32°C)\n   • Cuidados com pele: curativos não aderentes, atramáticos\n   • Prevenção de infecção: assepsia rigorosa\n\n3. SUPORTE VOLÊMICO:\n   • Similar ao grande queimado\n   • Fórmula de Parkland para NET > 30%: 4 mL/kg × % ASC em 24h\n\n4. CONTROLE DA DOR:\n   • Morfina IV, analgesia multimodal\n   • Sedação se necessário\n\n5. NUTRIÇÃO ENTERAL precoce (24–48h):\n   • Catabolismo intenso\n   • Meta: 25–35 kcal/kg/dia\n\n6. OLHOS:\n   • Colírio lubrificante frequente\n   • Consulta oftalmológica (pseudomembranas, simbléfaron)\n   • Risco de cegueira!\n\n7. BOCA:\n   • Bochechos com clorexidina\n   • Morfina oral/IV para odinofagia\n\n8. IMUNOSSUPRESSÃO (controversa — não evidência definitiva):\n   • IVIG 1g/kg/dia por 3 dias (mais estudada)\n   • Ciclosporina 3–5 mg/kg/dia (evidência favorável — centro especializado)\n   • Corticoide sistêmico: CONTRAINDICADO (aumenta infecção e mortalidade)\n\n9. ANTIBIÓTICO profilático: NÃO (aumenta resistência)\n   • Antibiótico SOMENTE se infecção confirmada" },
      { id: "followup", title: "Acompanhamento", content: "UTI/queimados:\n• Monitorar infecção (principal causa de morte)\n• Hemoculturas frequentes\n• Cuidado com mucosas até reepitelização\n\nSequelas:\n• Ocular: cicatriz, simbléfaron, olho seco, cegueira\n• Genital: fimose, estenose vaginal\n• Pulmão: bronquiolite obliterante (rara)\n• Pele: discromia, cicatrizes\n• Unhas: perda temporária\n\nRecorrência:\n• NUNCA reintroduzir a droga causadora\n• Documentar no prontuário e comunicar ao paciente" },
      { id: "treatment", title: "Abordagem Terapêutica", content: "IVIG: 1 g/kg/dia IV por 3 dias\nCiclosporina: 3 mg/kg/dia VO/IV (centro especializado)\nParkland: SF 0,9% ou RL → 4 mL × kg × % ASC nas primeiras 24h" },
      { id: "prescriptions", title: "Guia de Prescrições", content: "PRESCRIÇÃO: SJS/NET — EMERGÊNCIA\n\n1. SUSPENDER MEDICAMENTO CAUSADOR — IMEDIATAMENTE\n2. ACIONAR DERMATOLOGIA + QUEIMADOS + OFTALMOLOGIA\n3. CALCULAR ASC e SCORTEN (prognóstico)\n4. Ressuscitação volêmica (NET): RL 4 mL × ___kg × ___% ASC = ___mL/24h\n   (50% nas primeiras 8h, 50% nas próximas 16h)\n5. Morfina 2–4 mg IV SOS (dor intensa)\n6. Curativo de partes desnudadas: polietileno (cling film) ou pomada não aderente\n7. Temperatura do quarto: 28–32°C (minimizar perda de calor)\n8. Nutrição enteral: iniciar em 24–48h\n9. Colírio de lubrificação ocular: soro fisiológico e colírio 1/1h\n10. Bochechos com clorexidina 0,12% 6/6h\n11. IVIG 1 g/kg/dia IV por 3 dias (se disponível e centros especializados)\n12. Hemoculturas 48/48h\n13. Eletrólitos, albumina, função renal 12/12h\n14. Omeprazol 40mg IV 1x/dia\n\n⚠️ CORTICOIDE SISTÊMICO = CONTRAINDICADO\n⚠️ Antibiótico SOMENTE se infecção comprovada" },
      { id: "references", title: "Referências Bibliográficas", content: "1. Bastuji-Garin S et al. SCORTEN Score. J Invest Dermatol 2000.\n2. Harr T, French LE. Stevens-Johnson Syndrome and Toxic Epidermal Necrolysis. Chem Immunol Allergy 2012.\n3. Oakley AM, Krishnamurthy K. Stevens-Johnson Syndrome. StatPearls 2024.\n4. SBD. Protocolo de SJS/NET. An Bras Dermatol 2022." }
    ]
  }
];

// =================== ORTOPEDIA ===================
